"""Summary procedure, restoration and historical noncriminal-fact guard."""
import json,sys
from pathlib import Path
CPP='https://www.planalto.gov.br/ccivil_03/decreto-lei/del3689compilado.htm'
CP='https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm'
STF='https://portal.stf.jus.br/processos/listarProcessos.asp?classe=ADPF&numeroProcesso=395'
rows={}
def add(n,s,p,a,c,v,q,t,d,links=()):
 rows['art-'+str(n)]=dict(simples=s,pontos=p,atencao=[a],exemplo=c+' Variação: '+v,prova=q,termos=[dict(termo=t,significado=d)],remissoes=[CPP,*links])
add(531,'Audiência sumária tem prazo máximo legal de trinta dias e interrogatório depois da prova enumerada.', ['Ofendido se possível, testemunhas acusação/defesa, ressalva art.222.', 'Peritos, acareações, reconhecimento; acusado e debates.', 'Distinguir sessenta dias do ordinário.'], 'Prazo isolado não gera absolvição ou soltura automática sem análise pertinente.', 'Juízo organiza prova e ouve acusado ao final antes dos debates.', 'Prazo de sessenta do ordinário não substitui os trinta deste rito.', ['Prazo legal aqui é trinta dias? Sim.', 'Interrogatório vem antes de toda prova? Não.'], 'Instrução sumária','Audiência concentrada do rito sumário.')
add(532,'Sumário admite até cinco testemunhas arroladas pela acusação e cinco pela defesa.', ['Limite por lado, não conjunto.', 'Distinguir oito do ordinário.'], 'Não transportar limite ordinário de oito nem dizer cinco para todas as partes juntas.', 'Acusação e defesa indicam cada uma seu rol até cinco.', 'Ter vários advogados não multiplica automaticamente teto pelo número de profissionais.', ['Limite é cinco por lado? Sim.', 'Oito é o limite deste artigo? Não.'], 'Rol sumário','Número de testemunhas do rito pertinente.')
add(533,'Parágrafos do art.400 aplicam-se ao sumário: concentração, controle de pertinência e requerimento pericial prévio.', ['Parágrafos antigos deste artigo foram revogados.', 'Indeferimento de prova exige motivo pertinente.'], 'Não recuperar regras dos antigos §§1º–4º como atuais.', 'Parte pede esclarecimento de perito previamente.', 'Prova útil à defesa não pode ser recusada apenas por inconveniência à acusação.', ['Antigos parágrafos revogados são restaurados pela remissão? Não.', 'Regime do art.400 é integrado? Sim.'], 'Subsidiariedade probatória','Aplicação expressa dos parágrafos atuais indicados.')
add(534,'Alegações finais no sumário são orais: vinte minutos por lado prorrogáveis por dez, seguindo sentença.', ['Defesa individual por acusado.', 'Assistente tem dez após MP, com igual acréscimo defensivo.', 'Distinguir tempos longos do plenário do júri.'], 'Não dividir um só tempo defensivo entre vários acusados nem importar automaticamente todos os memoriais do ordinário sem examinar compatibilidade.', 'Cada acusado recebe seu tempo de defesa na hipótese do §1º.', 'Intervenção do assistente acrescenta igual tempo à defesa.', ['Defesa de cada acusado tem tempo individual? Sim.', 'Assistente amplia também tempo da defesa? Sim.'], 'Debates sumários','Manifestação final oral com paridade pertinente.')
add(535,'Adiamento no sumário depende de prova faltante imprescindível; condução deve respeitar limites constitucionais.', ['Não usar adiamento protelatório.', 'ADPFs395/444 vedam condução de acusado para interrogatório.', 'Parágrafos antigos revogados não retornam.'], 'Texto não autoriza conduzir réu coercitivamente para interrogatório nem afastar silêncio.', 'Testemunha indispensável ausente exige providência legal adequada.', 'Acusado não comparecer não permite transportá-lo à força para interrogatório.', ['A condução abrange interrogatório coercitivo do réu? Não.', 'Prova imprescindível pode justificar adiamento? Sim.'], 'Adiamento por prova','Exceção à concentração com garantias constitucionais.',[STF])
add(536,'Testemunha presente deve ser ouvida mesmo suspensa audiência, observada ordem do art.531.', ['Não desperdiçar presença útil.', 'Preservar sequência e contraditório.'], 'Oitiva de presente não permite embaralhar ordem por conveniência ou excluir defesa.', 'Uma testemunha está presente apesar de outra falta: seu depoimento é tomado no regime legal.', 'Não colher isoladamente sem regular participação defensiva.', ['Suspensão sempre impede ouvir presente? Não.', 'Ordem do art.531 permanece? Sim.'], 'Aproveitamento da presença','Produção útil da prova na ordem legal.')
add(538,'Remessa de infração de menor potencial pelo Juizado ao juízo comum leva ao procedimento sumário previsto.', ['Hipótese é encaminhamento para outro procedimento.', 'Não confundir procedimento sumário com sumaríssimo.', 'Não restaurar parágrafos revogados.'], 'Todo caso de menor potencial não sai automaticamente do Juizado nem segue ordinário pela simples remessa.', 'Juizado encaminha peças na hipótese legal e comum adota sumário.', 'Caso mantido no Juizado conserva regime próprio.', ['Remessa indicada leva ao sumário? Sim.', 'Sumário é idêntico ao sumaríssimo? Não.'], 'Remessa ao comum','Mudança de órgão e rito na situação legal.')
add(541,'Autos perdidos ou destruídos são restaurados na primeira instância, mesmo se desaparecimento ocorreu na segunda.', ['Cópia autêntica/certidão exibida pode valer como original.', 'Sem cópia: certificar estado e registros; requisitar reproduções institucionais.', 'Citação pessoal ou edital de dez dias se não encontradas partes.', 'Integrar evidências digitais autênticas sem inventar peças.'], 'Restauração não significa recriar conteúdo por suposição nem refazer processo ignorando cópia autêntica.', 'Backup autêntico exibido permite examinar substituição pelos termos legais.', 'Sem cópia, reunir registros e ouvir partes, não escrever sentença presumida.', ['Local da restauração é primeira instância? Sim.', 'Memória autoriza inventar documento? Não.'], 'Restauração de autos','Reconstrução controlada do processo perdido.')
add(542,'Partes são ouvidas no dia designado e termo registra concordâncias e conferência das reproduções apresentadas.', ['Contraditório sobre conteúdo recuperado.', 'Não impor acordo inexistente.'], 'Divergência deve ser tratada, não apagada no termo como consenso.', 'Partes concordam sobre documento autêntico e isso é registrado.', 'Uma parte contesta reprodução e divergência demanda exame.', ['Concordâncias devem ser registradas? Sim.', 'Pode declarar consenso inexistente? Não.'], 'Conferência contraditória','Exame conjunto do conteúdo reconstruído.')
add(543,'Diligências restauram prova e atos por fontes verificáveis, com participação das partes e MP.', ['Antes de sentença: reinquirir testemunhas; substituição se mortas ou não localizadas.', 'Perícia repetida quando possível, preferindo mesmos peritos.', 'Documentos por cópia autêntica ou, impossível, testemunhas.', 'Ouvir agentes que participaram dos atos; partes podem produzir prova do teor.'], 'Não repetir fisicamente exame impossível nem tratar lembrança como documento autêntico automaticamente.', 'Registro oficial e depoimentos pertinentes ajudam reconstruir ato perdido.', 'Vestígio consumido exige examinar possibilidade e fontes existentes, sem laudo inventado.', ['Perícia é repetida quando possível? Sim.', 'Partes podem provar teor perdido? Sim.'], 'Prova da restauração','Fontes que demonstram o conteúdo dos autos anteriores.')
add(544,'Diligências da restauração concluem em vinte dias salvo força maior; juiz pode requisitar esclarecimentos no prazo previsto de cinco dias.', ['Após diligências, conclusão para julgamento.', 'Poder de requisitar no curso e após conclusão conforme texto.'], 'Força maior é ressalva a examinar; prazo não legitima reconstrução sem prova.', 'Juízo reúne material e requisita esclarecimento indispensável.', 'Demora não autoriza aceitar versão fabricada para encerrar calendário.', ['Há ressalva de força maior? Sim.', 'Requisição de esclarecimento continua prevista? Sim.'], 'Conclusão da restauração','Prazos e esclarecimentos para decisão reconstrutiva.')
add(545,'Selos e taxas já pagos no processo original não são cobrados outra vez na restauração.', ['Verificar pagamento anterior.', 'Não presumir gratuidade universal de qualquer despesa nova.'], 'Regra evita duplicidade do que já foi pago, não elimina toda obrigação por definição.', 'Pagamento original demonstrado não é repetido.', 'Encargo distinto não se resolve apenas dizendo que toda restauração é gratuita.', ['Pagamento original pode ser cobrado de novo? Não.', 'Artigo cria gratuidade universal? Não.'], 'Vedação de duplicidade','Proteção contra nova cobrança do valor já pago.')
add(546,'Causador do extravio responde por custas em dobro, sem prejuízo de apuração criminal pertinente.', ['Identificar responsável e pressupostos.', 'Não culpar automaticamente acusado ou advogado.'], 'Responsabilidade penal exige enquadramento e prova, não apenas desaparecimento.', 'Apuração identifica agente responsável pelo extravio e consequências legais.', 'Falha sem responsável demonstrado não autoriza imputar crime ao réu do processo.', ['Custas previstas são em dobro? Sim.', 'Extravio prova crime do acusado original? Não.'], 'Responsabilidade pelo extravio','Consequências ao causador devidamente identificado.')
add(547,'Julgada restauração, autos restaurados valem como originais; se originais reaparecem durante ela, processo continua nestes com apenso.', ['Distinguir substituição válida e documento reencontrado.', 'Preservar histórico da restauração.'], 'Reaparecimento não autoriza apagar divergências ou destruir material reconstruído.', 'Originais reaparecem e restauração é apensada para continuidade.', 'Após julgamento pertinente, autos restaurados têm valor previsto, não mera anotação informal.', ['Restaurados julgados valem por originais? Sim.', 'Se originais reaparecem durante restauração, ela é apensada? Sim.'], 'Efeito da restauração','Valor processual da reconstrução decidida.')
add(548,'Condenação em execução pode manter efeitos durante restauração se sentença consta de guia ou registro inequívoco.', ['Não criar execução sem título verificável.', 'Limite temporal até decisão restauradora.', 'Controlar conteúdo e legalidade da execução.'], 'Perda dos autos não significa soltura automática nem legitima manter prisão sem demonstração inequívoca do título.', 'Guia autêntica confirma sentença em execução e permite análise da continuidade.', 'Rumor de condenação sem registro não preenche requisito.', ['Guia/registro inequívoco importa? Sim.', 'Rumor basta para execução? Não.'], 'Título na restauração','Demonstração da sentença executada apesar do extravio.')
add(549,'Texto descreve regime histórico de medida por fato não criminoso e remete a numeração antiga do CP, sem autorização atual geral.', ['CP reformado em 1984 tem pressupostos próprios de medida de segurança.', 'Não confundir política de saúde com sanção penal.', 'Periculosidade alegada não cria crime.'], 'Não ensinar inquérito para impor medida penal apenas por fato atípico ou condição pessoal.', 'Fato atípico não justifica sanção penal por mera classificação social de perigo.', 'Crime imputado com questão de imputabilidade exige processo e critérios atuais próprios.', ['Periculosidade isolada transforma fato atípico em crime? Não.', 'Numeração antiga deve ser integrada ao CP atual? Sim.'], 'Regime superado por integração','Remissão histórica que não restaura punição por condição pessoal.',[CP])
add(550,'Requerimento do MP deste procedimento acompanha antigo regime por fato não criminoso; não é via geral atual para sanção preventiva.', ['Texto exige descrição e fundamentos no modelo histórico.', 'Estudar separadamente ação penal por fato típico e cuidados não penais.'], 'Não substituir pressupostos atuais por simples pedido de medida apoiado em condição pessoal.', 'Pedido por crime efetivo segue acusação e garantias pertinentes.', 'Fato sem infração não ganha caráter penal porque MP pede medida histórica.', ['Pedido do MP cria crime? Não.', 'Regime atual exige base própria? Sim.'], 'Requerimento histórico','Peça do antigo procedimento, sujeita à integração atual.',[CP])
add(551,'Intimação para interrogatório deste procedimento histórico não permite forçar réu nem aplicar medida por fato atípico.', ['Identificar regime atual cabível.', 'Garantias constitucionais permanecem.', 'Não confundir interessado histórico e acusado de crime efetivo.'], 'Não usar artigo como exceção à vedação de condução para interrogatório.', 'Em processo penal atual, interrogatório observa silêncio e assistência.', 'Pessoa não pode ser levada à força para esse ato com base na regra histórica.', ['Autoriza interrogatório coercitivo por si? Não.', 'Garantias permanecem relevantes? Sim.'], 'Chamamento histórico','Ato que exige compatibilidade com direitos atuais.',[CP,STF])
add(552,'Prazo de dois dias e defensor nomeado pertencem ao antigo procedimento de medida por fato não criminoso.', ['Não substituir prazos atuais de defesa criminal.', 'Defesa técnica é garantia, não valida sanção sem base.'], 'Ter advogado não torna legítimo impor medida penal por atipicidade.', 'Acusação de crime segue prazo defensivo do rito atual adequado.', 'Dois dias deste modelo antigo não são prazo universal de resposta à acusação.', ['É prazo universal de resposta? Não.', 'Defensor cria base material para medida? Não.'], 'Defesa no modelo histórico','Garantia descrita em procedimento de aplicação limitada pela legislação posterior.',[CP])
add(553,'Exames, diligências e três testemunhas descritos integram o procedimento histórico, não limite geral contemporâneo.', ['Distinguir produção de prova atual conforme rito.', 'Perícia não converte comportamento atípico em infração penal.'], 'Não usar teto de três para toda discussão de imputabilidade ou medida de segurança.', 'Crime imputado exige perícia pertinente e prova com regime próprio.', 'Fato não criminoso não se transforma em crime pela conclusão de exame sobre condição pessoal.', ['Três é teto de todo processo penal atual? Não.', 'Perícia cria infração inexistente? Não.'], 'Prova no regime histórico','Atos antigos que exigem identificação de base atual.',[CP])
add(554,'Debates de dez minutos e segunda audiência em cinco dias pertencem ao modelo histórico de medida por fato não criminoso.', ['Não importar para procedimento comum, júri ou execução atual.', 'Decisão atual exige pressupostos materiais e processo pertinentes.'], 'Não ensinar esses tempos como regra atual geral para impor segurança penal.', 'Juízo aplica rito atual adequado a crime efetivamente imputado.', 'Atipicidade não é contornada abreviando debates pelo artigo antigo.', ['Debates de dez valem para todo processo atual? Não.', 'Rito histórico dispensa pressupostos atuais? Não.'], 'Decisão do modelo antigo','Etapa histórica sem autorização de sanção genérica contemporânea.',[CP])
add(555,'Remissões aos antigos arts.14/27 do CP não permitem impor medida automaticamente ao absolver ou impronunciar.', ['Integrar CP atual e hipóteses cabíveis de absolvição imprópria.', 'Impronúncia por falta de prova não equivale a inimputabilidade demonstrada.', 'Não tratar diagnóstico como título sancionatório.'], 'Não impor medida por simples insuficiência probatória ou por fato atípico com alegação de perigo.', 'Hipótese de medida exige examinar fato, imputabilidade e requisitos atuais.', 'Impronúncia por indícios insuficientes não gera internação punitiva automática.', ['Impronúncia impõe medida automaticamente? Não.', 'Remissão antiga dispensa base atual? Não.'], 'Integração da medida','Aplicação apenas com pressupostos atuais pertinentes.',[CP])
assert len(rows)==22
Path(sys.argv[1]).write_text(json.dumps({'course_slug':'codigo-processo-penal','units':rows},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(len(rows),'summary restoration units reviewed')
